static void test_settings_set_tenant_override_reaches_its_route_refuses_without_a_scope(void) {
    axiam_client_t *c = mgmt_unscoped_client();
    axiam_error_t err;
    axiam_mgmt_tenant_settings_override_t body;
    memset(&body, 0, sizeof(body));
    axiam_error_kind_t rc = axiam_settings_set_tenant_override(c, NULL, &body, NULL, &err);

    TEST_ASSERT_EQUAL_INT(AXIAM_ERR_NETWORK, rc);
    /*
     * 1, not 0: the login itself is a request. What matters is that NO management request
     * followed it.
     */
    TEST_ASSERT_EQUAL_INT(1, mgmt_request_count());
    axiam_client_free(c);
}

